-- Run after the service trust cards migration. Add supplied service images only.
begin;
do $$
declare s public.cms_sections%rowtype; entry jsonb; updated jsonb; target_path text[]; parent_path text[];
begin
 for s in select * from public.cms_sections where (page_id='services' or page_id like 'services--%') for update loop
  updated := s.data;
  for entry in select value from jsonb_array_elements('[{"page": "services--chemical-liquid-cargo-transportation", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/services/chemical-and-liquid-cargo-transportation/logo-1.png"}, {"page": "services--chemical-liquid-cargo-transportation", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/services/chemical-and-liquid-cargo-transportation/logo-2.png"}, {"page": "services--chemical-liquid-cargo-transportation", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/services/chemical-and-liquid-cargo-transportation/logo-3.png"}, {"page": "services--chemical-liquid-cargo-transportation", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/services/chemical-and-liquid-cargo-transportation/logo-4.png"}, {"page": "services--chemical-liquid-cargo-transportation", "section": "sectionFive", "path": ["clients", "4", "image"], "image": "/services/chemical-and-liquid-cargo-transportation/logo-5.png"}, {"page": "services--chemical-liquid-cargo-transportation", "section": "sectionOne", "path": ["image"], "image": "/services/chemical-and-liquid-cargo-transportation/section-1-main-image.png"}, {"page": "services--chemical-liquid-cargo-transportation", "section": "sectionFour", "path": ["image"], "image": "/services/chemical-and-liquid-cargo-transportation/section-4-main-image.png"}, {"page": "services--containerized-transportation", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/services/containerized-transportation/logo-1.png"}, {"page": "services--containerized-transportation", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/services/containerized-transportation/logo-2.png"}, {"page": "services--containerized-transportation", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/services/containerized-transportation/logo-3.png"}, {"page": "services--containerized-transportation", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/services/containerized-transportation/logo-4.png"}, {"page": "services--containerized-transportation", "section": "sectionOne", "path": ["image"], "image": "/services/containerized-transportation/section-1-main-image.png"}, {"page": "services--containerized-transportation", "section": "sectionFour", "path": ["image"], "image": "/services/containerized-transportation/section-4-main-image.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/services/dry-cargo-transportation/logo-1.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/services/dry-cargo-transportation/logo-2.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/services/dry-cargo-transportation/logo-3.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/services/dry-cargo-transportation/logo-4.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionFive", "path": ["clients", "4", "image"], "image": "/services/dry-cargo-transportation/logo-5.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionFive", "path": ["clients", "5", "image"], "image": "/services/dry-cargo-transportation/logo-6.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionOne", "path": ["image"], "image": "/services/dry-cargo-transportation/section-1-main-image.png"}, {"page": "services--dry-cargo-transportation", "section": "sectionFour", "path": ["image"], "image": "/services/dry-cargo-transportation/section-4-main-image.png"}, {"page": "services--flatbed-transportation", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/services/flatbed-transportation/logo-1.png"}, {"page": "services--flatbed-transportation", 