rvices--heavy-project-cargo", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/services/heavy-and-project-cargo/logo-3.png"}, {"page": "services--heavy-project-cargo", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/services/heavy-and-project-cargo/logo-4.png"}, {"page": "services--heavy-project-cargo", "section": "sectionOne", "path": ["image"], "image": "/services/heavy-and-project-cargo/section-1-main-image.png"}, {"page": "services--heavy-project-cargo", "section": "sectionFour", "path": ["image"], "image": "/services/heavy-and-project-cargo/section-4-main-image.png"}, {"page": "services", "section": "sectionOne", "path": ["image"], "image": "/services/overview/section-1-main-image.png"}, {"page": "services--petroleum-transportation", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/services/petroleum-transportation/logo-1.png"}, {"page": "services--petroleum-transportation", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/services/petroleum-transportation/logo-2.png"}, {"page": "services--petroleum-transportation", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/services/petroleum-transportation/logo-3.png"}, {"page": "services--petroleum-transportation", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/services/petroleum-transportation/logo-4.png"}, {"page": "services--petroleum-transportation", "section": "sectionFive", "path": ["clients", "4", "image"], "image": "/services/petroleum-transportation/logo-5.png"}, {"page": "services--petroleum-transportation", "section": "sectionOne", "path": ["image"], "image": "/services/petroleum-transportation/section-1-main-image.png"}, {"page": "services--petroleum-transportation", "section": "sectionFour", "path": ["image"], "image": "/services/petroleum-transportation/section-4-main-image.png"}, {"page": "services--road-freight-transportation", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/services/road-freight-transportation/logo-1.png"}, {"page": "services--road-freight-transportation", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/services/road-freight-transportation/logo-2.png"}, {"page": "services--road-freight-transportation", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/services/road-freight-transportation/logo-3.png"}, {"page": "services--road-freight-transportation", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/services/road-freight-transportation/logo-4.png"}, {"page": "services--road-freight-transportation", "section": "sectionFive", "path": ["clients", "4", "image"], "image": "/services/road-freight-transportation/logo-5.png"}, {"page": "services--road-freight-transportation", "section": "sectionFive", "path": ["clients", "5", "image"], "image": "/services/road-freight-transportation/logo-6.png"}, {"page": "services--road-freight-transportation", "section": "sectionOne", "path": ["image"], "image": "/services/road-freight-transportation/section-1-main-image.png"}]'::jsonb) loop
   if entry->>'page'=s.page_id and entry->>'section'=s.key then
    select array_agg(value order by ord) into target_path from jsonb_array_elements_text(entry->'path') with ordinality as a(value,ord);
    parent_path := target_path[1:cardinality(target_path)-1];
    if cardinality(target_path)=1 or (jsonb_typeof(updated#>parent_path)='object' and updated#>parent_path<>'{}'::jsonb) then
     updated := jsonb_set(updated,target_path,entry->'image');
    end if;
   end if;
  end loop;
  if updated is distinct from s.data then
   update public.cms_sections set data=updated,revision=revision+1,updated_at=now() where page_id=s.page_id and key=s.key;
   insert into public.cms_history(actor,actor_id,page_id,section,revision,changes)
   values('System: Service page images added','00000000-0000-0000-0000-000000000000'::uuid,s.page_id,s.key,s.revision+1,public.cms_diff(s.data,updated));
  end if;
 end loop;
end $$;
commit;
